+  /* Сбрасываем боковые марджины, их теперь идеально держат паддинги бацькі */
+  margin-top: 72px;
+  margin-bottom: 0;
+  margin-left: 0;
+  margin-right: 0;
+  
+  width: 531px;
+  flex-shrink: 0; /* Запрещаем сжимать левую часть */
+  box-sizing: border-box;
+  align-self: flex-start;
+}
+
+
+.construction_repair_gomel {
+    font-family: 'Roboto', sans-serif;
+  font-size: 60px;
+  line-height: 70px;
+  font-weight: bold;
+  color: #ffffff;
+  margin: 0;
+}
+.button {
+  width: 300px;
+  height: 51px;
+  margin: 85px 265px 53px 32px;
+  padding: 14px 35.9px 21px 34px;
+  border-radius: 10px;
+  color: #ffffff;
+  border: solid 3px #ff7a00;
+  background-color: #1c1d1e;
+  cursor: pointer;
+  transition: background-color 0.3s ease, color 0.3s ease;
+  box-sizing: border-box;
+}
+
+.button:hover {
+  background-color: #ff7a00;
+  color: #1c1d1e ; 
+}
+
+.future_together {
+   width: 321px;
+   margin: 73px 247px 85px 29px;
+  font-size: 22px;
+  font-weight: 400;
+}
+.main_content_block {
+ display: flex;
+  flex-direction: row;
+  
+  /* Жесткие габариты контентной зоны из макета */
+  width: 1440px;
+  height: 520px; 
+  margin: 6px auto 0 auto; 
+  
+  /* 1. Натуральный поток элементов слева направо */
+  justify-content: flex-start; 
+  align-items: center;
+  
+  /* 2. Отступы по краям всей нашей 1440-пиксельной сетки */
+  padding-left: 29px;   /* Левый край текста — строго 29px */
+  padding-right: 112px; /* Правый край рамки слайдера — строго 112px */
+  
+  /* 3. ЖЕСТКИЙ ЧЕСТНЫЙ ЗАЗОР ИЗ МАКЕТА PIXSO */
+  column-gap: 131px; /* То то самое расстояние между контентом текста и рамкой */
+  
+  position: relative;
+  box-sizing: border-box;
+}
+
+.slider_container {
+ width: 658px;
+}
+
+.slider {
+  width: 640px;
+  position: relative;
+}
+
+.slideImage {
+  width: 100%;
+  height: auto;
+  object-fit: cover;
+}
+
+.slick-dots {
+  position: absolute;
+  bottom: 20px;
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  justify-content: center;
+  list-style: none;
+  padding: 0;
+  margin: 0;
+}
+
+.slick-dots li button {
+  width: 10px;
+  height: 10px;
+  border-radius: 50%;
+  background-color: rgba(255, 255, 255, 0.5);
+  border: none;
+  cursor: pointer;
+  margin: 0 5px;
+  padding: 0;
+}
+
+.slick-dots li.slick-active button {
+  background-color: white;
+}
+
+.main_content_block {
+  display: flex;
+  flex-direction: row;
+  align-items: center;
+  justify-content: space-between;
+  width: 100%;
+}
+
+
+
+.arrow {
+  position: absolute;
+  top: 50%;
+  transform: translateY(-50%);
+  z-index: 10;
+  cursor: pointer;
+  width: 28.7px;
+  height: 57.5px;
+  border: solid 1px #ff7a00;
+  display: flex;
+  justify-content: center;
+  align-items: center;
+  font-size: 24px;
+  color: #ff7a00;
+  background-color: rgba(0, 0, 0, 0.5);
+}
+
+.nextArrow {
+  right: 20px;
+}
+
+.prevArrow {
+  left: 20px;
+}

